void mergeParts(vector<int>& values, int left, int mid, int right) {
    vector<int> merged;
    int i = left, j = mid + 1;
    while (i <= mid && j <= right) {
        if (values[i] <= values[j]) merged.push_back(values[i++]);
        else merged.push_back(values[j++]);
    }
