bool wildcardMatch(const string& pattern, const string& text) {
    int n = pattern.size(), m = text.size();
    vector<vector<bool>> dp(n + 1, vector<bool>(m + 1, false));
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        if (pattern[i - 1] == '*') dp[i][0] = dp[i - 1][0];
